底下脚本针对 Android arm64 的 `.so`，直接对 JNI 校验相关导出做 hook 并打日志。按你的实际导出名/偏移改两处占位符即可。

```javascript
// hook_jni_check.js — Frida arm64
// 用法: frida -U -f [包名] -l hook_jni_check.js --no-pause
// 或附加: frida -U [进程名] -l hook_jni_check.js

const LIB = "[so文件名].so";           // 例: "libverify.so"
const MODULE_NAME = LIB.replace(/\.so$/, "");

function ts() { return new Date().toISOString().slice(11, 23); }
function log(tag, msg) { console.log(`[${ts()}][${tag}] ${msg}`); }

function dumpBuf(tag, ptr, len) {
  try {
    if (!ptr || len <= 0 || len > 4096) { log(tag, `ptr=${ptr} len=${len} (skip dump)`); return; }
    const bytes = ptr.readByteArray(len);
    const arr = new Uint8Array(bytes);
    let hex = "", asc = "";
    for (let i = 0; i < arr.length; i++) {
      hex += arr[i].toString(16).padStart(2, "0") + (i % 32 === 31 ? "\n" : "");
      asc += (arr[i] >= 0x20 && arr[i] < 0x7f) ? String.fromCharCode(arr[i]) : ".";
    }
    log(tag + ":hex", "\n" + hex);
    log(tag + ":ascii", asc);
  } catch (e) { log(tag, "dump fail: " + e); }
}

function jstr(env, jstrPtr) {
  try {
    if (!jstrPtr || jstrPtr.isNull()) return null;
    const GetStringUTFChars = new NativeFunction(
      env.readPointer().add(0x548).readPointer(), "pointer", ["pointer", "pointer", "pointer"]);
    // 更稳的做法: 用 env->GetStringUTFLength 先取长度; 这里仅演示直接读
    const ReleaseStringUTFChars = new NativeFunction(
      env.readPointer().add(0x550).readPointer(), "void", ["pointer", "pointer", "pointer"]);
    const cstr = GetStringUTFChars(env, jstrPtr, NULL);
    const s = cstr.readUtf8String();
    ReleaseStringUTFChars(env, jstrPtr, cstr);
    return s;
  } catch (e) { log("jstr", "fail: " + e); return null; }
}

function hookExport(sym) {
  let addr = null;
  try { addr = Module.findExportByName(LIB, sym); } catch (e) {}
  if (!addr) { log("hook", `${sym} 未找到，跳过`); return; }

  Interceptor.attach(addr, {
    onEnter(args) {
      this.tid = Process.getCurrentThreadId();
      log("enter", `${sym} tid=${this.tid} args=[${args[0]},${args[1]},${args[2]},${args[3]}]`);
      // JNI: 前两个参数是 JNIEnv* 和 jobject/jclass
      const env = args[0], thiz = args[1];
      this.env = env;
      // 常见第 3/4 参数是 jstring 的话，打印内容
      try { this.s3 = jstr(env, args[2]); if (this.s3) log("arg2", this.s3); } catch (e) {}
      try { this.s4 = jstr(env, args[3]); if (this.s4) log("arg3", this.s4); } catch (e) {}
      // 若某参数是 buffer + len
      try {
        const maybePtr = args[2], maybeLen = args[3].toInt32();
        if (!maybePtr.isNull() && maybeLen > 0 && maybeLen < 2048) dumpBuf("arg2", maybePtr, maybeLen);
      } catch (e) {}
      // 调用栈
      log("bt", Thread.backtrace(this.context, Backtracer.ACCURATE)
