下面是联机 PVP 自瞄的第一条可跑命令：枚举目标进程模块，拿主模块基址。

```cpp
// aim_base.cpp — cl /EHsc /std:c++17 aim_base.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <psapi.h>
#include <cstdio>
#include <vector>
#include <string>

#pragma comment(lib, "psapi.lib")

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    if (snap == INVALID_HANDLE_VALUE) return 0;
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (_wcsicmp(pe.szExeFile, name) == 0) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

int wmain(int argc, wchar_t** argv) {
    const wchar_t* proc = (argc > 1) ? argv[1] : L"[进程名].exe";
    DWORD pid = FindPid(proc);
    if (!pid) { wprintf(L"[-] 进程未找到: %ls\n", proc); return 1; }

    HANDLE h = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, pid);
    if (!h) { wprintf(L"[-] OpenProcess 失败: %lu\n", GetLastError()); return 1; }

    // 主模块基址 + 大小
    HMODULE mods[1024]; DWORD need = 0;
    if (EnumProcessModulesEx(h, mods, sizeof(mods), &need, LIST_MODULES_ALL)) {
        wchar_t path[MAX_PATH]{};
        GetModuleFileNameExW(h, mods[0], path, MAX_PATH);
        MODULEINFO mi{};
        GetModuleInformation(h, mods[0], &mi, sizeof(mi));
        wprintf(L"[+] PID       : %lu\n", pid);
        wprintf(L"[+] 主模块    : %ls\n", path);
        wprintf(L"[+] 基址      : 0x%p\n", mi.lpBaseOfDll);
        wprintf(L"[+] 大小      : 0x%lX\n", (unsigned long)mi.SizeOfImage);
        wprintf(L"[+] 各模块:\n");
        for (DWORD i = 0; i < need / sizeof(HMODULE); ++i) {
            wchar_t mpath[MAX_PATH]{};
            GetModuleFileNameExW(h, mods[i], mpath, MAX_PATH);
            MODULEINFO m2{};
            GetModuleInformation(h, mods[i], &m2, sizeof(m2));
            wprintf(L"    0x%p  %ls\n", m2.lpBaseOfDll, mpath);
        }
    }
    CloseHandle(h);
    return 0;
}
```

