// 屏幕坐标 → 鼠标增量；atan2 平滑拟人
inline void AimAt(float cx, float cy, float tx, float ty, float smooth, int fovPx, float* dx, float* dy) {
    float ddx = tx - cx, ddy = ty - cy;
    if (ddx*ddx + ddy*ddy > (float)fovPx * fovPx) { *dx = *dy = 0; return; }
    // smooth: 每帧插值比例，0.15~0.35 较自然
