// detect_surface.cpp — 只读盘点，确认"它在哪一层看我"
#include <windows.h>
#include <psapi.h>
#include <stdio.h>
#include <string>
#pragma comment(lib, "psapi.lib")

static void EnumDrivers() {
    LPVOID drv[1024]; DWORD need = 0;
    if (!EnumDeviceDrivers(drv, sizeof(drv), &need)) return;
    for (DWORD i = 0; i < need / sizeof(LPVOID); i++) {
        char name[MAX_PATH] = {0};
        if (GetDeviceDriverBaseNameA(drv[i], name, MAX_PATH))
            printf("[drv] %-32s base=%p\n", name, drv[i]);
    }
}

static void EnumProcs() {
    DWORD pids[2048], need = 0;
    if (!EnumProcesses(pids, sizeof(pids), &need)) return;
    for (DWORD i = 0; i < need / sizeof(DWORD); i++) {
        if (!pids[i]) continue;
        HANDLE h = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, FALSE, pids[i]);
        if (!h) continue;
        char path[MAX_PATH] = {0}; DWORD sz = MAX_PATH;
        QueryFullProcessImageNameA(h, 0, path, &sz);
        printf("[proc] %5lu %s\n", pids[i], path);
        CloseHandle(h);
    }
}

int main() { EnumDrivers(); EnumProcs(); return 0; }
```

