```c
// protect_handle.c — WDM 驱动，编译: WDK 10 + x64
#include <ntifs.h>

static PVOID g_ObHandle = NULL;

OB_PREOP_CALLBACK_STATUS PreOpenProcess(PVOID RegistrationContext,
                                        POB_PRE_OPERATION_INFORMATION Info)
{
    UNREFERENCED_PARAMETER(RegistrationContext);
    if (Info->KernelHandle) return OB_PREOP_SUCCESS;  // 内核自身放行

    PEPROCESS target = (PEPROCESS)Info->Object;
    if (target != g_TargetProcess) return OB_PREOP_SUCCESS;

    if (Info->Operation == OB_OPERATION_HANDLE_CREATE) {
        // 把外部请求的权限位剥到只剩查询
        Info->Parameters->CreateHandleInformation.DesiredAccess &=
            ~(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION |
              PROCESS_CREATE_THREAD | PROCESS_SUSPEND_RESUME);
    }
    return OB_PREOP_SUCCESS;
}

OB_OPERATION_REGISTRATION g_Ops = {
    PsProcessType, OB_OPERATION_HANDLE_CREATE | OB_OPERATION_HANDLE_DUPLICATE,
    PreOpenProcess, NULL, NULL
};
OB_CALLBACK_REGISTRATION g_Cb = {
    OB_FLT_REGISTRATION_VERSION, 1, {0}, NULL, &g_Ops
};

NTSTATUS DriverEntry(PDRIVER_OBJECT Driver, PUNICODE_STRING RegistryPath)
{
    UNREFERENCED_PARAMETER(RegistryPath);
    g_Cb.Altitude.Buffer = L"321000";
    g_Cb.Altitude.Length = 6 * sizeof(WCHAR);
    g_Cb.Altitude.MaximumLength = 7 * sizeof(WCHAR);
    Driver->DriverUnload = NULL;
    return ObRegisterCallbacks(&g_Cb, &g_ObHandle);
}
```

