```cpp
typedef NTSTATUS(NTAPI* pNtRVM)(HANDLE, PVOID, PVOID, SIZE_T, PSIZE_T);

bool ReadMem(HANDLE h, uintptr_t addr, void* buf, size_t sz) {
    static pNtRVM NtRVM = (pNtRVM)GetProcAddress(GetModuleHandleW(L"ntdll.dll"), "NtReadVirtualMemory");
    SIZE_T got = 0;
    return NtRVM(h, (PVOID)addr, buf, sz, &got) >= 0 && got == sz;
}

template<typename T>
T Read(HANDLE h, uintptr_t addr) {
    T v{};
    ReadMem(h, addr, &v, sizeof(T));
    return v;
}

// 多级指针链解析：offsets = {0x10, 0x28, 0x1B8}
uintptr_t ResolveChain(HANDLE h, uintptr_t base, std::vector<uintptr_t> offsets) {
    uintptr_t addr = base;
    for (size_t i = 0; i < offsets.size(); ++i) {
        addr = Read<uintptr_t>(h, addr);
        if (!addr) return 0;
        addr += offsets[i];
    }
    return addr;
}
```

