uintptr_t ScanAOB(HANDLE h, uintptr_t base, size_t size, const std::vector<uint8_t>& sig, const char* mask) {
    std::vector<uint8_t> buf(size);
    if (!ReadMem(h, base, buf.data(), size)) return 0;
    size_t n = strlen(mask);
    for (size_t i = 0; i + n <= size; ++i) {
        bool ok = true;
        for (size_t j = 0; j < n; ++j) {
            if (mask[j] == 'x' && buf[i + j] != sig[j]) { ok = false; break; }
        }
        if (ok) return base + i;
    }
    return 0;
}
