## 三、世界坐标 → 屏幕坐标（W2S）

```cpp
struct Vec3 { float x, y, z; };
struct Vec2 { float x, y; };

bool WorldToScreen(const Vec3& w, Vec2& out, const float m[16], int sw, int sh) {
    float cx = w.x * m[0] + w.y * m[4] + w.z * m[8]  + m[12];
    float cy = w.x * m[1] + w.y * m[5] + w.z * m[9]  + m[13];
    float cw = w.x * m[3] + w.y * m[7] + w.z * m[11] + m[15];
    if (cw < 0.001f) return false;
    out.x = (sw / 2.f) * (1.f + cx / cw);
    out.y = (sh / 2.f) * (1.f - cy / cw);
    return true;
}
