## 1. 读内存与取矩阵

```cpp
// mem.h
#pragma once
#include <windows.h>
#include <cstdint>

struct Vec2 { float x, y; };
struct Vec3 { float x, y, z; };

class Mem {
public:
    HANDLE h{ nullptr };
    uintptr_t base{ 0 };

    bool Attach(const wchar_t* proc) {
        DWORD pid = 0;
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        PROCESSENTRY32W pe{ sizeof(pe) };
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe)) {
            if (!_wcsicmp(pe.szExeFile, proc)) { pid = pe.th32ProcessID; break; }
        }
        CloseHandle(snap);
        if (!pid) return false;
        h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!h) return false;
        base = GetModuleBase(pid, L"[模块名]");
        return base != 0;
    }

    static uintptr_t GetModuleBase(DWORD pid, const wchar_t* mod) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        MODULEENTRY32W me{ sizeof(me) };
        for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me)) {
            if (!_wcsicmp(me.szModule, mod)) { uintptr_t b = (uintptr_t)me.modBaseAddr; CloseHandle(snap); return b; }
        }
        CloseHandle(snap);
        return 0;
    }

    template <typename T>
    bool Read(uintptr_t addr, T& out) {
        return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), nullptr) != 0;
    }

    // 多级指针链：offsets 从外到内，最后一级是字段偏移
    uintptr_t ResolveChain(uintptr_t addr, const std::initializer_list<uintptr_t>& offsets) {
        uintptr_t cur = addr;
        for (uintptr_t off : offsets) {
            if (!Read(cur + off, cur)) return 0;
        }
        return cur;
    }
};
```

## 2. W2S 矩阵

```cpp
// w2s.h
#pragma once
#include "mem.h"

struct Mat4 { float m[4][4]; };

// 视图矩阵：RowMajor 的 ViewProjection（多数 UE / Unity / RE 引擎通用）
// 偏移占位：[视图矩阵偏移] 用 Mem::ResolveChain 取到矩阵首地址后 Read<Mat4>
inline bool WorldToScreen(const Vec3& world, Vec2& screen, const Mat4& vp, int w, int h) {
    float cx = world.x * vp.m[0][0] + world.y * vp.m[1][0] + world.z * vp.m[2][0] + vp.m[3][0];
    float cy = world.x * vp.m[0][1] + world.y * vp.m[1][1] + world.z * vp.m[2][1] + vp.m[3][1];
    float cz = world.x * vp.m[0][2] + world.y * vp.m[1][2] + world.z * vp.m[2][2] + vp.m[3][2];
    float cw = world.x * vp.m[0][3] + world.y * vp.m[1][3] + world.z * vp.m[2][3] + vp.m[3][3];

    if (cw < 0.001f) return false;               // 在背后
    float inv = 1.0f / cw;
    float nx = cx * inv, ny = cy * inv;

    screen.x = (nx + 1.0f) * 0.5f * (float)w;
    screen.y = (1.0f - ny) * 0.5f * (float)h;
    return screen.x >= 0 && screen.y >= 0 && screen.x < w && screen.y < h;
}
```

