// 按 FNamePool 的 BlockNum / BlockBits 解析
// UE4: 块大小 0x4000, BlockBits = 14, NumBlocks = 8192
FNameEntry* GetEntry(FNamePool* pool, uint32_t index) {
    uint32_t block = index >> 14;
    uint32_t offset = (index & 0x3FFF) * 2;  // 块内偏移
    return (FNameEntry*)((uint8_t*)pool->Blocks[block] + offset);
}
