// 2) 多级指针链解析：base + [偏移0] → +偏移1 → ... → 目标地址
static BOOL rpm(HANDLE h, ULONGLONG addr, void* buf, SIZE_T n) {
    return ReadProcessMemory(h, (LPCVOID)addr, buf, n, NULL);
}

ULONGLONG resolve(HANDLE h, ULONGLONG base, const ULONGLONG* chain, int n) {
    ULONGLONG addr = base + chain[0];
    for (int i = 1; i < n; i++) {
        if (!rpm(h, addr, &addr, sizeof(addr))) return 0;
        addr += chain[i];
    }
    return addr;
}
