```cpp
// rw.cpp — Windows x64, MSVC /MT, 编译: cl /O2 /EHsc rw.cpp
#include <windows.h>
#include <tlhelp32.h>
#include <cstdio>
#include <vector>
#include <string>

static DWORD FindPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static uintptr_t GetModBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

template <typename T>
T Rpm(HANDLE h, uintptr_t addr) {
    T v{};
    SIZE_T n = 0;
    ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(T), &n);
    return v;
}

// 多级指针链：module + base_off, 然后每级 add_off 后解引用
uintptr_t ResolveChain(HANDLE h, uintptr_t modBase, uintptr_t baseOff,
                       const std::vector<uintptr_t>& chain) {
    uintptr_t p = Rpm<uintptr_t>(h, modBase + baseOff);
    for (size_t i = 0; i + 1 < chain.size(); ++i) {
        if (!p) return 0;
        p = Rpm<uintptr_t>(h, p + chain[i]);
    }
    return p ? p + chain.back() : 0;
}

int wmain(int argc, wchar_t** argv) {
    if (argc < 3) { wprintf(L"usage: rw.exe <进程名.exe> <模块名.dll/exe>\n"); return 1; }
    DWORD pid = FindPid(argv[1]);
    if (!pid) { wprintf(L"[-] pid not found\n"); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE |
                           PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION,
                           FALSE, pid);
    if (!h) { wprintf(L"[-] OpenProcess failed: %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModBase(pid, argv[2]);
    wprintf(L"[+] pid=%lu base=%s + 0x%llX\n", pid, argv[2], (unsigned long long)base);

    // 占位：真实值靠 CE / 静态分析拿到后填这里
    // baseOff = 0x[模块内静态偏移], chain = { 0x[一级], 0x[二级], 0x[末级数值偏移] }
    const uintptr_t baseOff = 0x[模块内静态偏移];
    std::vector<uintptr_t> chain = { 0x[1], 0x[2], 0x[3] };
    uintptr_t addr = ResolveChain(h, base, baseOff, chain);
    wprintf(L"[+] final addr = 0x%llX\n", (unsigned long long)addr);

    if (addr) {
        // 先 dump 原值，任何写入都要能回滚
        int orig = Rpm<int>(h, addr);
        wprintf(L"[*] orig value = %d\n", orig);
        // int v = 9999;
        // WriteProcessMemory(h, (LPVOID)addr, &v, sizeof(v), nullptr);
    }
    CloseHandle(h);
    return 0;
}
