#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD GetPid(const char* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32 pe = { .dwSize = sizeof(pe) };
    DWORD pid = 0;
    if (Process32First(snap, &pe))
        do { if (!_stricmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; } }
        while (Process32Next(snap, &pe));
    CloseHandle(snap);
    return pid;
}

static uintptr_t GetModBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me = { .dwSize = sizeof(me) };
    uintptr_t base = 0;
    if (Module32FirstW(snap, &me))
        do { if (!_wcsicmp(me.szModule, mod)) { base = (uintptr_t)me.modBaseAddr; break; } }
        while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return base;
}

static bool ReadChain(HANDLE h, uintptr_t base, const DWORD* offs, int n, uintptr_t* out) {
    uintptr_t p = base;
    for (int i = 0; i < n; i++) {
        if (!ReadProcessMemory(h, (LPCVOID)(p + offs[i]), &p, sizeof(p), NULL)) return false;
        if (!p) return false;
    }
    *out = p;
    return true;
}

int main(void) {
    DWORD pid = GetPid("[进程名]");
    if (!pid) { printf("process not found\n"); return 1; }
    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION, FALSE, pid);
    if (!h) { printf("OpenProcess fail: %lu\n", GetLastError()); return 1; }

    uintptr_t base = GetModBase(pid, L"[模块名]");
    printf("pid=%lu base=0x%p\n", pid, (void*)base);

    // 偏移链：[偏移1] >> [偏移2] >> [偏移3] ... 末尾是要读的字段
    DWORD chain[] = { [偏移1], [偏移2], [偏移3] };
    uintptr_t obj = 0;
    if (ReadChain(h, base, chain, 3, &obj)) {
        int hp = 0;
        ReadProcessMemory(h, (LPCVOID)obj, &hp, sizeof(hp), NULL);
        printf("value @0x%p = %d\n", (void*)obj, hp);
    } else {
        printf("chain fail: %lu\n", GetLastError());
    }
    CloseHandle(h);
    return 0;
}
