```cpp
// mem.h —— 用户态读写封装（先跑通读，再谈写）
#include <windows.h>
#include <tlhelp32.h>
#include <vector>

struct ModuleInfo { uintptr_t base; size_t size; };

inline DWORD GetPid(const wchar_t* procName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) do {
        if (!_wcsicmp(pe.szExeFile, procName)) { CloseHandle(snap); return pe.th32ProcessID; }
    } while (Process32NextW(snap, &pe));
    CloseHandle(snap);
    return 0;
}

inline ModuleInfo GetModule(HANDLE hProc, const wchar_t* modName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32,
                                           GetProcessId(hProc));
    MODULEENTRY32W me{ sizeof(me) };
    ModuleInfo info{ 0, 0 };
    if (Module32FirstW(snap, &me)) do {
        if (!_wcsicmp(me.szModule, modName)) {
            info.base = (uintptr_t)me.modBaseAddr;
            info.size = me.modBaseSize;
            break;
        }
    } while (Module32NextW(snap, &me));
    CloseHandle(snap);
    return info;
}

inline bool Read(HANDLE h, uintptr_t addr, void* buf, size_t sz) {
    SIZE_T n = 0;
    return ReadProcessMemory(h, (LPCVOID)addr, buf, sz, &n) && n == sz;
}

template <typename T>
inline T ReadT(HANDLE h, uintptr_t addr) {
    T v{};
    Read(h, addr, &v, sizeof(T));
    return v;
}
