// ULevel + [ACTORLIST_OFF]             -> TArray<AActor*>
// AActor + [MESH_OFF]                  -> USkeletalMeshComponent*
// USkeletalMeshComponent + [BONECACHE] -> FTransform* 数组
constexpr uintptr_t WORLD_OFF       = 0x0;  // [偏移]
constexpr uintptr_t ACTORLIST_OFF   = 0x0;  // [偏移]
constexpr uintptr_t MESH_OFF        = 0x0;  // [偏移]
constexpr uintptr_t BONECACHE_OFF   = 0x0;  // [偏移]
constexpr uintptr_t BONECOUNT_OFF   = 0x0;  // [偏移]
constexpr uintptr_t TEAM_OFF        = 0x0;  // [偏移]
constexpr uintptr_t HEALTH_OFF      = 0x0;  // [偏移]

bool GetBonePos(uintptr_t actor, int boneIdx, Vec3& out) {
    uintptr_t mesh = 0, cache = 0;
    if (!RPM(actor + MESH_OFF, mesh) || !mesh) return false;
    if (!RPM(mesh + BONECACHE_OFF, cache) || !cache) return false;

    // UE 的 FTransform：Quat(4f) + Translation(3f) + Scale(3f)，Translation 在 +0x10
    // EU 版本不同，偏移先用 [BONE_STRIDE] 占位，实战用 CE 扫真实 stride
    constexpr uintptr_t BONE_STRIDE = 0x30;   // [偏移]
    constexpr uintptr_t TRANSLATION = 0x10;   // [偏移]
    return RPM(cache + boneIdx * BONE_STRIDE + TRANSLATION, out);
}

// 以头部骨骼（通常 8/头）做瞄准点
bool GetAimPoint(uintptr_t actor, Vec3& out) {
    constexpr int HEAD_BONE = 8; // [骨骼索引]
    return GetBonePos(actor, HEAD_BONE, out);
}
